function localStoryDay(){const d=new Date();return [d.getFullYear(),d.getMonth()+1,d.getDate()].join('-');/* Code by Daniel using ChatGPT November 10, 2026 */}
function dialogueHTML(block){return `<h2 id="panel-title">${escapeHTML(block.title)}</h2>${block.lines.map(function line(t){return `<p>${escapeHTML(t.replace(/^Traveler:/,elfName()+':'))}</p>`;/* Code by Daniel using ChatGPT November 10, 2026 */}).join('')}<p class="verse-meta">${(block.scripture_refs||[]).map(escapeHTML).join(' · ')}</p>`;/* Code by Daniel using ChatGPT November 10, 2026 */}
function toyStatus(id){return state.quest.toys[id]||'lost';/* Code by Daniel using ChatGPT November 10, 2026 */}
function showQuestMap(){talesQuestMap();/* Code by Daniel using ChatGPT November 11, 2026 */}
function collectToy(id){if(taleCollectToy(id))return;if(toyStatus(id)!=='lost')return;state.quest.toys[id]='found';save();const toy=TOYS.find(function current(t){return t.id===id;/* Code by Daniel using ChatGPT November 10, 2026 */});showPanel(`<h2 id="panel-title">${escapeHTML(toy.title)}</h2><p>A little snow, a loose part, and a toy someone has missed. You lift it carefully into your bag.</p><p>The workshop has a warm bench and the tools for the repair.</p><div class="row"><button class="primary" id="toy-keep">Keep exploring</button><button id="toy-workshop">Walk to the workshop</button></div>`,'A TREASURE TO CARRY HOME');$('#toy-keep').onclick=closePanel;$('#toy-workshop').onclick=function goRepair(){closePanel();planRoom('workshop');/* Code by Daniel using ChatGPT November 10, 2026 */};/* Code by Daniel using ChatGPT November 10, 2026 */}
function repairBench(){if(!g.benchIntroduced){g.benchIntroduced=true;talkBlock09(TOY_QUEST_CONTENT.repair,'keeper',repairBench);return;}const carried=TOYS.filter(function needsRepair(t){return ['found','cleaned','mended'].includes(toyStatus(t.id));/* Code by Daniel using ChatGPT November 10, 2026 */});showPanel(`<h2 id="panel-title" class="action-prompt">Choose a toy to mend</h2><div class="collection-list">${carried.map(function repairChoice(t){return `<button data-repair="${t.id}">${escapeHTML(t.title)}<small>${toyStatus(t.id)}</small></button>`;/* Code by Daniel using ChatGPT November 10, 2026 */}).join('')||'<p>No toys need a repair at the moment. The map will show where to look and who is waiting.</p>'}</div><button id="bench-map">Read the map</button>`,'THE REPAIR BENCH');panel.querySelectorAll('[data-repair]').forEach(function wireRepair(b){b.onclick=function chooseToy(){repairToy(b.dataset.repair);/* Code by Daniel using ChatGPT November 10, 2026 */};/* Code by Daniel using ChatGPT November 10, 2026 */});$('#bench-map').onclick=showQuestMap;/* Code by Daniel using ChatGPT November 10, 2026 *//* Code by Daniel using ChatGPT November 12, 2026 */}
function repairToy(id){if(TOYS.some(function knownToy10(t){return t.id===id;/* Code by Daniel using ChatGPT November 13, 2026 */})&&['found','cleaned','mended'].includes(toyStatus(id)))openActivity10('repair',id);else repairBench();/* Code by Daniel using ChatGPT November 13, 2026 */}

