function showRimeEncounter(){showPanel(`${dialogueHTML(TOY_QUEST_CONTENT.rescue_caught)}<div class="row"><button class="primary" id="escape-read">Read three cards together</button><button id="escape-recall">Try optional three-card recall</button><button id="escape-quiet">Take the quiet way out</button></div>`,'A LARGE SCARF ACROSS THE PASSAGE');$('#escape-read').onclick=function readEscape(){escapeCards(0,false);/* Code by Daniel using ChatGPT November 10, 2026 */};$('#escape-recall').onclick=function recallEscape(){escapeCards(0,true);/* Code by Daniel using ChatGPT November 10, 2026 */};$('#escape-quiet').onclick=function quietExit(){closePanel();requestAction(ROOMS.cave.spots[0]);/* Code by Daniel using ChatGPT November 10, 2026 */};/* Code by Daniel using ChatGPT November 10, 2026 */}
function escapeCards(index,recall){const refs=TOY_QUEST_CONTENT.mechanics.escape_cards;if(index>=3){showPanel(`<h2 id="panel-title">The path is clear</h2><p>${escapeHTML(TOY_QUEST_CONTENT.rescue_caught.complete_line)}</p><button class="primary" id="escape-done">Continue exploring</button>`,'THREE WORDS OF HOPE');$('#escape-done').onclick=closePanel;return;}const ref=refs[index],card=cards.find(function matching(c){return c.title.replace(/\s*\([^)]*\)/g,'').replace(/–/g,'-')===ref;/* Code by Daniel using ChatGPT November 10, 2026 */});if(!card){showPanel(`<h2 id="panel-title">${escapeHTML(ref)}</h2><p>This passage is not in your loaded Scripture collection. Read it together in your Bible, or import the passage when your collection is ready.</p><button class="primary" id="missing-next">We read together · continue</button><button id="missing-quiet">The quiet way out</button>`,'A REFERENCE TO READ TOGETHER');$('#missing-next').onclick=function nextMissing(){escapeCards(index+1,recall);/* Code by Daniel using ChatGPT November 10, 2026 */};$('#missing-quiet').onclick=closePanel;return;}if(recall){startPractice(card.id,function nextEscape(){escapeCards(index+1,true);/* Code by Daniel using ChatGPT November 10, 2026 */});return;}state.learned[card.id]=card.fingerprint;refreshCount();save();showPanel(`<p class="verse-meta">${index+1} / 3 · READ TOGETHER</p><h2 id="panel-title">${escapeHTML(card.title)}</h2><blockquote>${escapeHTML(plain(card.text))}</blockquote><p>${escapeHTML(card.translation)}</p><button class="primary" id="escape-next">${index===2?'Carry these words onward':'Read the next card'}</button><button id="escape-quiet">The quiet way out</button>`,'THE WORDS BEFORE THE CHALLENGE');$('#escape-next').onclick=function nextCard(){escapeCards(index+1,false);/* Code by Daniel using ChatGPT November 10, 2026 */};$('#escape-quiet').onclick=closePanel;/* Code by Daniel using ChatGPT November 10, 2026 */}
function readBridge(){talesNotice('The lantern on the bridge','<p>The lamp shows only the next few boards. Beyond it, the pines are dark with snow.</p><p>You cross slowly, one hand upon the rail. On the far bank, someone lifts another light.</p><p>For now, there is enough to take the next step.</p>','BETWEEN TWO BANKS');/* Code by Daniel using ChatGPT November 11, 2026 */}
